<script setup lang="ts">
import { onMounted,onUnmounted,ref } from 'vue'
import { getSession } from './api'
import { users,userAction,type User } from './systemManagement'
const rows=ref<User[]>([]),busy=ref(false),error=ref(''),message=ref(''),username=ref(''),password=ref(''),createConsent=ref(false),target=ref(''),resetPassword=ref(''),resetConsent=ref(false),toggleConsent=ref<Record<string,boolean>>({}),uncertain=ref(false)
let alive=true,revision=0
async function read(){const token=++revision;busy.value=true;rows.value=[];error.value='';uncertain.value=false;password.value='';resetPassword.value='';createConsent.value=false;resetConsent.value=false;toggleConsent.value={};try{const result=await users();if(alive&&token===revision)rows.value=result.users}catch(e){if(alive&&token===revision)error.value=(e as Error).message}finally{if(alive&&token===revision)busy.value=false}}
async function mutate(action:()=>Promise<unknown>){if(busy.value||uncertain.value)return;busy.value=true;message.value='';const token=revision;try{await action();if(!alive||revision!==token)return;message.value='账号操作已完成；重置或停用会撤销该教师的已有会话。';target.value='';await read()}catch{if(alive&&token===revision){error.value='账号操作未能确认，请先刷新账号状态核实，不会自动重试。';uncertain.value=true}}finally{password.value='';resetPassword.value='';createConsent.value=false;resetConsent.value=false;if(alive)busy.value=false}}
onMounted(read);onUnmounted(()=>{alive=false;revision++;password.value='';resetPassword.value='';rows.value=[]})
</script>
<template><section><h2>用户管理</h2><p>只管理教师账号；教师使用用户名与密码，无邮箱、无登录OTP。本入口不修改管理员账号。</p><button @click="read" :disabled="busy">刷新用户列表</button><p v-if="error" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
 <template v-if="getSession()?.role==='admin'"><form @submit.prevent="mutate(()=>userAction('create',username.trim(),password,createConsent))"><fieldset :disabled="busy||uncertain"><legend>创建教师账号</legend><label>教师用户名<input v-model="username" required pattern="[A-Za-z][A-Za-z0-9_.-]{2,63}" autocomplete="off" @input="createConsent=false"></label><label>教师初始密码<input type="password" v-model="password" required minlength="12" maxlength="512" autocomplete="new-password" @input="createConsent=false"></label><label class="check"><input type="checkbox" v-model="createConsent">我确认创建此教师账号</label><button :disabled="!createConsent">创建教师</button></fieldset></form>
 <article v-for="u in rows" :key="u.username" class="point-record"><h3>{{ u.username }}</h3><p>{{ u.role==='admin'?'管理员':'教师' }} · {{ u.enabled?'启用':'停用' }}</p><template v-if="u.role==='teacher'"><fieldset :disabled="busy||uncertain"><legend>管理{{ u.username }}</legend><button @click="target=u.username;resetPassword='';resetConsent=false">重置{{ u.username }}密码</button><label class="check"><input type="checkbox" v-model="toggleConsent[u.username]">确认{{ u.enabled?'停用并撤销会话':'恢复' }}{{ u.username }}</label><button @click="mutate(()=>userAction(u.enabled?'disable':'enable',u.username,'',!!toggleConsent[u.username]))" :disabled="!toggleConsent[u.username]">{{ u.enabled?'停用':'恢复' }}{{ u.username }}</button></fieldset></template></article>
 <form v-if="target" @submit.prevent="mutate(()=>userAction('reset-password',target,resetPassword,resetConsent))"><fieldset :disabled="busy||uncertain"><legend>重置{{ target }}密码</legend><label>教师新密码<input type="password" v-model="resetPassword" required minlength="12" maxlength="512" autocomplete="new-password" @input="resetConsent=false"></label><label class="check"><input type="checkbox" v-model="resetConsent">确认重置密码并撤销旧会话</label><button :disabled="!resetConsent">确认重置教师密码</button><button type="button" @click="target='';resetPassword='';resetConsent=false">取消重置</button></fieldset></form>
 </template>
</section></template>
